<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Falling‑Sand Sandbox</title>
<style>
  body{margin:0;background:#222;color:#eee;font-family:sans-serif;display:flex;flex-direction:column;align-items:center}
  #controls{margin:10px;}
  button{background:#444;border:none;padding:6px 12px;margin:2px;color:#eee;border-radius:4px;cursor:pointer}
  button.active{background:#888}
  canvas{border:1px solid #555;background:#111}
</style>
</head>
<body>
<div id="controls">
  <button id="mat-sand" class="active">Sand</button>
  <button id="mat-water">Water</button>
  <button id="mat-wall">Wall</button>
  <button id="mat-acid">Acid</button>
  <button id="mat-empty">Eraser</button>
  <button id="clear">Clear</button>
</div>
<canvas id="sand" width="400" height="400"></canvas>

<script>
(() => {
const canvas = document.getElementById('sand');
const ctx = canvas.getContext('2d');
const CELL_SIZE = 5; // pixels per cell
const COLS = Math.floor(canvas.width / CELL_SIZE);   // >=80
const ROWS = Math.floor(canvas.height / CELL_SIZE);
const colors = {
  empty: '#111',
  sand: '#D4A657',
  water: '#3C7EB9',
  wall: '#555',
  acid: '#8B0000'
};
let grid = Array.from({length: ROWS}, () => Array(COLS).fill('empty'));
let curMat = 'sand';
let mouseDown = false;

// UI
const btns = {
  sand: document.getElementById('mat-sand'),
  water: document.getElementById('mat-water'),
  wall: document.getElementById('mat-wall'),
  acid: document.getElementById('mat-acid'),
  empty: document.getElementById('mat-empty')
};
Object.values(btns).forEach(b=>{
  b.addEventListener('click',()=>{curMat=b.id.split('-')[1];updateActive();});
});
function updateActive(){
  Object.values(btns).forEach(b=>b.classList.toggle('active',b.id.includes(curMat)));
}
btns.empty.addEventListener('click',()=>{mouseDown=false;}); // disable drawing
document.getElementById('clear').addEventListener('click',sim.clear);

canvas.addEventListener('mousedown',e=>{
  mouseDown=true;
  paint(e);
});
canvas.addEventListener('mousemove',e=>{if(mouseDown)paint(e);});
canvas.addEventListener('mouseup',()=>mouseDown=false);
canvas.addEventListener('mouseleave',()=>mouseDown=false);

function paint(e){
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor((e.clientX - rect.left)/CELL_SIZE);
  const y = Math.floor((e.clientY - rect.top)/CELL_SIZE);
  if(x>=0 && x<COLS && y>=0 && y<ROWS){
    sim.set(x,y,curMat);
  }
}

// Simulation engine
function step(){
  const newGrid = grid.map(row=>row.slice());
  for(let y=ROWS-1;y>=0;y--){
    for(let x=0;x<COLS;x++){
      const cell = grid[y][x];
      if(cell==='empty' || cell==='wall') continue;
      let targetX=x, targetY=y;
      // fall
      if(y+1<ROWS){
        const below = grid[y+1][x];
        if(below==='empty'){
          targetY=y+1;
        }else if((cell==='sand'||cell==='acid') && (below==='water' || below==='acid')){
          // swap with water or acid
          newGrid[y+1][x]=cell;
          newGrid[y][x]='empty';
          continue;
        }
      }
      // side movement for water/acid
      if(targetY===y){
        const dirs = [ -1, 1 ];
        if(Math.random()<0.5) dirs.reverse();
        for(const d of dirs){
          const nx=x+d;
          if(nx>=0 && nx<COLS){
            const ncell=grid[y][nx];
            if(ncell==='empty'){
              targetX=nx;break;
            }
          }
        }
      }
      // apply move
      if(targetY!==y || targetX!==x){
        newGrid[targetY][targetX]=cell;
        newGrid[y][x]='empty';
      }

      // Acid dissolving neighbors
      if(cell==='acid'){
        const neigh = [
          [x-1,y],[x+1,y],[x,y-1],[x,y+1]
        ];
        for(const [nx,ny] of neigh){
          if(nx>=0 && nx<COLS && ny>=0 && ny<ROWS){
            if(grid[ny][nx]==='sand' || grid[ny][nx]==='wall'){
              newGrid[ny][nx]='empty';
            }
          }
        }
      }
    }
  }
  grid=newGrid;
}

function render(){
  for(let y=0;y<ROWS;y++){
    for(let x=0;x<COLS;x++){
      ctx.fillStyle = colors[grid[y][x]];
      ctx.fillRect(x*CELL_SIZE,y*CELL_SIZE,CELL_SIZE,CELL_SIZE);
    }
  }
}

// Animation loop
let lastTime=0;
function loop(time){
  if(time-lastTime>50){ // ~20fps
    step();
    render();
    lastTime=time;
  }
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// API exposure
window.sim = {
  w: COLS,
  h: ROWS,
  tick(n=1){
    for(let i=0;i<n;i++){
      step();
    }
    render();
  },
  get(x,y){ return grid[y][x]; },
  set(x,y,m){ if(m==='empty'){grid[y][x]='empty';} else {grid[y][x]=m;} },
  clear(){ grid = Array.from({length: ROWS}, () => Array(COLS).fill('empty')); render(); }
};
})();
</script>
</body>
</html>
